function Field({label,children}:{label:string;children:React.ReactNode}){return <div className="grid gap-1.5"><label className="text-sm font-medium">{label}</label>{children}</div>}
function Section({id,title,children}:{id:string;title:React.ReactNode;children:React.ReactNode}){return <Card id={id}><CardHeader><CardHeading>{title}</CardHeading></CardHeader><CardContent className="grid gap-5">{children}</CardContent></Card>}

